module ComfyUI.Assets.DialogServiceB6M7p8yrJsMap

let file = """{"version":3,"file":"dialogService-B6M7p8yr.js","names":["$t","$emit","$t","$t","$t"],"sources":["../../src/utils/executionErrorUtil.ts","../../src/scripts/appRegistry.ts","../../src/platform/errorCatalog/catalogIds.ts","../../src/platform/errorCatalog/runtimeErrorMatcher.ts","../../src/platform/settings/composables/useSettingsDialog.ts","../../src/components/dialog/content/ConfirmationDialogContent.vue","../../src/components/dialog/content/ConfirmationDialogContent.vue","../../src/components/common/NoResultsPlaceholder.vue","../../src/components/common/NoResultsPlaceholder.vue","../../src/components/dialog/content/error/FindIssueButton.vue","../../src/components/dialog/content/error/FindIssueButton.vue","../../src/platform/errorCatalog/catalogI18n.ts","../../src/platform/errorCatalog/runtimeErrorCopy.ts","../../src/platform/errorCatalog/executionErrorResolver.ts","../../src/platform/errorCatalog/promptErrorResolver.ts","../../src/platform/errorCatalog/validationErrorResolver.ts","../../src/platform/missingMedia/missingMediaGrouping.ts","../../src/platform/missingModel/missingModelGrouping.ts","../../src/platform/errorCatalog/missingErrorResolver.ts","../../src/platform/errorCatalog/errorMessageResolver.ts","../../src/utils/errorReportUtil.ts","../../src/components/dialog/content/ErrorDialogContent.vue","../../src/components/dialog/content/ErrorDialogContent.vue","../../src/components/dialog/content/PromptDialogContent.vue","../../src/components/dialog/content/PromptDialogContent.vue","../../src/services/dialogService.ts"],"sourcesContent":["import type { NodeError, PromptError } from '@/platform/remote/comfyui/types'\nimport type { SerializedNodeId } from '@/types/nodeId'\n\ntype RawPromptError =\n  | string\n  | { type?: string; message?: string; details?: string }\n\n/**\n * The standard prompt validation response shape (`{ error, node_errors }`).\n * In cloud, this is embedded as JSON inside `execution_error.exception_message`\n * because prompts are queued asynchronously and errors arrive via WebSocket\n * rather than as direct HTTP responses.\n */\ninterface CloudValidationError {\n  error?: RawPromptError\n  node_errors?: Record<SerializedNodeId, NodeError>\n}\n\nexport function isCloudValidationError(\n  value: unknown\n): value is CloudValidationError {\n  return (\n    value !== null &&\n    typeof value === 'object' &&\n    ('error' in value || 'node_errors' in value)\n  )\n}\n\n/**\n * Extracts a prompt validation response embedded in an exception message string.\n *\n * Cloud example `exception_message`:\n *   \"Failed to send prompt request: ... 400: {\\\"error\\\":{...},\\\"node_errors\\\":{...}}\"\n *\n * This function finds the first '{' and parses the trailing JSON.\n */\nexport function tryExtractValidationError(\n  exceptionMessage: string\n): CloudValidationError | null {\n  const jsonStart = exceptionMessage.indexOf('{')\n  const jsonEnd = exceptionMessage.lastIndexOf('}')\n  if (jsonStart === -1 || jsonEnd === -1) return null\n\n  try {\n    const parsed: unknown = JSON.parse(\n      exceptionMessage.substring(jsonStart, jsonEnd + 1)\n    )\n    return isCloudValidationError(parsed) ? parsed : null\n  } catch {\n    return null\n  }\n}\n\ntype CloudValidationResult =\n  | { kind: 'nodeErrors'; nodeErrors: Record<SerializedNodeId, NodeError> }\n  | { kind: 'promptError'; promptError: PromptError }\n\nexport function normalizePromptError(error: unknown): PromptError | null {\n  if (error !== null && typeof error === 'object') {\n    return {\n      type:\n        'type' in error && typeof error.type === 'string'\n          ? error.type\n          : 'error',\n      message:\n        'message' in error && typeof error.message === 'string'\n          ? error.message\n          : '',\n      details:\n        'details' in error && typeof error.details === 'string'\n          ? error.details\n          : ''\n    }\n  }\n\n  return typeof error === 'string'\n    ? { type: 'error', message: error, details: '' }\n    : null\n}\n\nexport function isMissingNodePromptError(\n  promptError: PromptError | null | undefined\n): boolean {\n  return promptError?.type === 'missing_node_type'\n}\n\n/**\n * Classifies an embedded cloud validation error from `exception_message`\n * as either node-level errors or a prompt-level error.\n *\n * Returns `null` if the message does not contain a recognizable validation error.\n */\nexport function classifyCloudValidationError(\n  exceptionMessage: string\n): CloudValidationResult | null {\n  const extracted = tryExtractValidationError(exceptionMessage)\n  if (!extracted) return null\n\n  const { error, node_errors } = extracted\n  const hasNodeErrors = node_errors && Object.keys(node_errors).length > 0\n\n  if (hasNodeErrors) {\n    return { kind: 'nodeErrors', nodeErrors: node_errors }\n  }\n\n  const promptError = normalizePromptError(error)\n  return promptError ? { kind: 'promptError', promptError } : null\n}\n\nexport function errorsForSlot(\n  errors: NodeError['errors'],\n  slotName: string\n): NodeError['errors'] {\n  return errors.filter((error) => error.extra_info?.input_name === slotName)\n}\n\nexport function hasErrorForSlot(\n  errors: NodeError['errors'],\n  slotName: string\n): boolean {\n  return errors.some((error) => error.extra_info?.input_name === slotName)\n}\n\n/**\n * Error types that can be resolved automatically when the user changes a\n * widget value or establishes a connection, without requiring a re-run.\n *\n * When adding new types, review {@link isValueStillOutOfRange} to ensure\n * the new type does not require range validation before auto-clearing.\n */\nexport const SIMPLE_ERROR_TYPES = new Set([\n  'value_bigger_than_max',\n  'value_smaller_than_min',\n  'value_not_in_list',\n  'required_input_missing'\n])\n\nexport type NodeValidationError = NodeError['errors'][number]\n\nexport const INPUT_LEVEL_VALIDATION_ERROR_TYPES = new Set([\n  'required_input_missing',\n  'bad_linked_input',\n  'return_type_mismatch',\n  'invalid_input_type',\n  'value_smaller_than_min',\n  'value_bigger_than_max',\n  'value_not_in_list',\n  'custom_validation_failed',\n  'exception_during_inner_validation'\n])\n\nexport const NODE_LEVEL_VALIDATION_ERROR_TYPES = new Set([\n  'PARTNER_NODE_DISABLED',\n  'exception_during_validation',\n  'dependency_cycle'\n])\n\n/** Decodes the `[type, { min, max, ... }]` tuple the backend attaches to range errors. */\nexport function getInputConfigBounds(error: NodeValidationError): {\n  min?: unknown\n  max?: unknown\n} {\n  const config = error.extra_info?.input_config\n  if (!Array.isArray(config)) return {}\n\n  const bounds = config[1]\n  if (!bounds || typeof bounds !== 'object') return {}\n\n  const { min, max } = bounds as { min?: unknown; max?: unknown }\n  return { min, max }\n}\n\nexport function isImageNotLoadedValidationError(\n  error: NodeValidationError\n): boolean {\n  return (\n    error.type === 'custom_validation_failed' &&\n    /invalid image file|\\[errno 21\\].*is a directory/i.test(\n      [error.message, error.details].filter(Boolean).join('\\n')\n    )\n  )\n}\n\n// Anything not input-level (including unknown types) is node-level.\nexport function isNodeLevelValidationError(\n  error: NodeValidationError\n): boolean {\n  return (\n    !INPUT_LEVEL_VALIDATION_ERROR_TYPES.has(error.type) ||\n    isImageNotLoadedValidationError(error)\n  )\n}\n\n/**\n * Returns true if `value` still violates a recorded range constraint.\n * Pass errors already filtered to the target widget (by `input_name`).\n * `options` should contain the widget's configured `min` / `max`.\n *\n * Returns true (keeps the error) when a bound is unknown (`undefined`).\n */\nexport function isValueStillOutOfRange(\n  value: number,\n  errors: NodeError['errors'],\n  options: { min?: number; max?: number }\n): boolean {\n  const hasMaxError = errors.some((e) => e.type === 'value_bigger_than_max')\n  const hasMinError = errors.some((e) => e.type === 'value_smaller_than_min')\n\n  return (\n    (hasMaxError && (options.max === undefined || value > options.max)) ||\n    (hasMinError && (options.min === undefined || value < options.min))\n  )\n}\n","import { assert } from '@/base/assert'\nimport type { ComfyApp } from '@/types/comfy'\n\nlet instance: ComfyApp | undefined\n\n/**\n * Called once by `@/scripts/app` after it constructs the singleton. Modules\n * that the app imports cannot import `@/scripts/app` back without a cycle, so\n * they reach the instance through `useApp` from `@/scripts/appInstance`.\n */\nexport function registerApp(app: ComfyApp) {\n  instance = app\n}\n\nexport function useApp(): ComfyApp {\n  assert(instance, 'ComfyApp accessed before registerApp')\n  return instance\n}\n","// FE-resolved catalog IDs that either normalize multiple sources or do not map\n// 1:1 to an API error type. Simple validation mappings stay with the validation\n// resolver.\nexport const MISSING_CONNECTION_CATALOG_ID = 'missing_connection'\nexport const UNKNOWN_VALIDATION_ERROR_CATALOG_ID = 'unknown_validation_error'\nexport const EXECUTION_FAILED_CATALOG_ID = 'execution_failed'\nexport const IMAGE_NOT_LOADED_CATALOG_ID = 'image_not_loaded'\nexport const OUT_OF_MEMORY_CATALOG_ID = 'out_of_memory'\nexport const CONTENT_BLOCKED_CATALOG_ID = 'content_blocked'\nexport const ACCESS_REQUIRED_CATALOG_ID = 'access_required'\nexport const MODEL_ACCESS_ERROR_CATALOG_ID = 'model_access_error'\nexport const INVALID_CLIP_INPUT_CATALOG_ID = 'invalid_clip_input'\nexport const INVALID_PROMPT_CATALOG_ID = 'invalid_prompt'\nexport const INVALID_WORKFLOW_REQUEST_CATALOG_ID = 'invalid_workflow_request'\nexport const INSUFFICIENT_CREDITS_CATALOG_ID = 'insufficient_credits'\nexport const WORKSPACE_INSUFFICIENT_CREDITS_CATALOG_ID =\n  'workspace_insufficient_credits'\nexport const SUBSCRIPTION_REQUIRED_CATALOG_ID = 'subscription_required'\nexport const SUBSCRIPTION_UPGRADE_REQUIRED_CATALOG_ID =\n  'subscription_upgrade_required'\nexport const MODEL_DOWNLOAD_FAILED_CATALOG_ID = 'model_download_failed'\nexport const UNEXPECTED_SERVICE_ERROR_CATALOG_ID = 'unexpected_service_error'\nexport const REQUEST_FAILED_CATALOG_ID = 'request_failed'\nexport const RUN_START_FAILED_CATALOG_ID = 'run_start_failed'\nexport const RUN_ENDED_UNEXPECTEDLY_CATALOG_ID = 'run_ended_unexpectedly'\nexport const SIGN_IN_REQUIRED_CATALOG_ID = 'sign_in_required'\nexport const RATE_LIMITED_CATALOG_ID = 'rate_limited'\nexport const TIMEOUT_CATALOG_ID = 'timeout'\nexport const GENERATION_STALLED_CATALOG_ID = 'generation_stalled'\nexport const PREPROCESSING_FAILED_CATALOG_ID = 'preprocessing_failed'\nexport const PREPROCESSING_TIMEOUT_CATALOG_ID = 'preprocessing_timeout'\nexport const SERVER_CRASHED_CATALOG_ID = 'server_crashed'\nexport const SERVER_BUSY_CATALOG_ID = 'server_busy'\n","import {\n  ACCESS_REQUIRED_CATALOG_ID,\n  CONTENT_BLOCKED_CATALOG_ID,\n  GENERATION_STALLED_CATALOG_ID,\n  IMAGE_NOT_LOADED_CATALOG_ID,\n  INSUFFICIENT_CREDITS_CATALOG_ID,\n  INVALID_CLIP_INPUT_CATALOG_ID,\n  INVALID_PROMPT_CATALOG_ID,\n  INVALID_WORKFLOW_REQUEST_CATALOG_ID,\n  MODEL_ACCESS_ERROR_CATALOG_ID,\n  MODEL_DOWNLOAD_FAILED_CATALOG_ID,\n  OUT_OF_MEMORY_CATALOG_ID,\n  PREPROCESSING_FAILED_CATALOG_ID,\n  PREPROCESSING_TIMEOUT_CATALOG_ID,\n  RATE_LIMITED_CATALOG_ID,\n  REQUEST_FAILED_CATALOG_ID,\n  RUN_ENDED_UNEXPECTEDLY_CATALOG_ID,\n  RUN_START_FAILED_CATALOG_ID,\n  SERVER_BUSY_CATALOG_ID,\n  SERVER_CRASHED_CATALOG_ID,\n  SIGN_IN_REQUIRED_CATALOG_ID,\n  SUBSCRIPTION_REQUIRED_CATALOG_ID,\n  SUBSCRIPTION_UPGRADE_REQUIRED_CATALOG_ID,\n  TIMEOUT_CATALOG_ID,\n  UNEXPECTED_SERVICE_ERROR_CATALOG_ID,\n  WORKSPACE_INSUFFICIENT_CREDITS_CATALOG_ID\n} from './catalogIds'\nimport type { CatalogParams } from './catalogI18n'\n\n// Runtime errors can share generic exception labels, so targeted cataloging\n// relies on narrow stable messages. Keep these matches exact or prefix-based.\nconst INSUFFICIENT_CREDITS_MESSAGES = new Set([\n  'Payment Required: Please add credits to your account to use this node.'\n])\nconst WORKSPACE_INSUFFICIENT_CREDITS_MESSAGES = new Set([\n  // Execution-time (pre-GPU) WebSocket failure for a queued team job.\n  'Payment Required: Please add credits to your workspace to continue.',\n  // Submit-time 429 rejection for a team workspace out of credits\n  // (checkTeamWorkspaceSubscription). It shares the PAYMENT_REQUIRED error type\n  // with the subscription-required rejection, so it can only be told apart by\n  // message.\n  'Insufficient credits to queue workflows'\n])\nconst SUBSCRIPTION_REQUIRED_MESSAGES = new Set([\n  'Workspace has no active subscription. Please subscribe to a plan to continue.',\n  'User has no active subscription. Please subscribe to a plan to continue.',\n  'Subscription required to queue workflows'\n])\nconst SUBSCRIPTION_UPGRADE_REQUIRED_PREFIX =\n  'the following private models require a subscription upgrade:'\nconst TIMEOUT_MESSAGES = new Set(['Job execution time exceeded maximum limit'])\nconst GENERATION_STALLED_MESSAGES = new Set([\n  'Job went too long without making any progress',\n  'Job has stagnated'\n])\nconst SERVER_CRASHED_MESSAGES = new Set([\n  'RIP to the server your workflow was running on.',\n  'Inference service restarted, terminating job',\n  'Job stuck in erroring state, forcing terminal transition',\n  'Job was previously marked as lost and has now been acknowledged by inference service'\n])\nconst SERVER_BUSY_MESSAGES = new Set([\n  'Failed to enqueue job for processing',\n  'Executor is busy with another job',\n  'Servers are busy. Please try again later.'\n])\nconst INVALID_WORKFLOW_REQUEST_MESSAGES = new Set([\n  'The workflow request is invalid.',\n  'Invalid job: missing workflow',\n  \"Invalid workflow: missing 'prompt' field\",\n  \"Invalid workflow: 'prompt' field must be an object\"\n])\nconst ACCESS_REQUIRED_MESSAGE =\n  'This run requires access that is not available for the current account.'\nconst MODEL_ACCESS_ERROR_MESSAGE =\n  'One or more required models could not be accessed.'\nconst UNEXPECTED_SERVICE_ERROR_MESSAGE = 'Unexpected service error.'\nconst REQUEST_FAILED_MESSAGE =\n  'The request failed before the run could complete.'\nconst RUN_START_FAILED_MESSAGE = 'The run could not be started.'\nconst RUN_ENDED_UNEXPECTEDLY_MESSAGE = 'The run ended unexpectedly.'\nconst SIGN_IN_REQUIRED_MESSAGE =\n  'Unauthorized: Please login first to use this node.'\nconst RATE_LIMITED_PREFIX = 'Rate Limit Exceeded:'\nconst CORE_OOM_TIP = 'This error means you ran out of memory on your GPU.'\nconst CORE_OOM_ALLOCATION_PREFIX = 'Allocation on device'\nconst CLOUD_OOM_PREFIX =\n  'Workflow execution failed due to insufficient memory (OOM).'\nconst ERRNO_DIRECTORY_MESSAGE = '[Errno 21] Is a directory:'\nconst INVALID_CLIP_INPUT_PREFIX = 'ERROR: clip input is invalid: None'\nconst PROMPT_TOO_SHORT_MESSAGE =\n  \"Field 'prompt' cannot be shorter than 1 characters; was 0 characters long.\"\nconst PROMPT_EMPTY_MESSAGE = \"Field 'prompt' cannot be empty.\"\nconst PREPROCESSING_FAILED_MESSAGE = 'Preprocessing failed'\nconst PREPROCESSING_TIMEOUT_MESSAGES = new Set([\n  'Preprocessing timed out',\n  'Preprocessing timed out.'\n])\nconst MODEL_DOWNLOAD_PANIC_PREFIX = 'internal error during model download:'\nconst GENERATED_VIDEO_REJECTED_MESSAGE =\n  'Generated video rejected by content moderation.'\nconst GENERATED_CONTENT_REJECTED_MESSAGE =\n  'Generated content was rejected by a safety check.'\nconst SAFETY_CHECK_MESSAGE = 'Prompt or Initial Image failed the safety checks.'\nconst CONTENT_POLICY_VIOLATION_MESSAGE =\n  'The generated image was flagged for content policy violation.'\nconst CONTENT_MODERATION_FLAGGED_PREFIX =\n  'Your request was flagged by our content moderation system'\nconst GOOGLE_RAI_FILTERED_PREFIX =\n  \"Content filtered by Google's Responsible AI practices\"\nconst GOOGLE_RAI_BLOCKED_PREFIX =\n  \"Content blocked by Google's Responsible AI filters\"\n\nconst START_FAILED_PREFIXES = [\n  'Failed to start WebSocket client:',\n  'Failed to get ComfyUI generation ID:'\n]\nconst REQUEST_FAILED_PREFIXES = ['Failed to send prompt request:']\nconst SERVER_CRASHED_PREFIXES = [\n  'Workflow execution was interrupted due to ComfyUI process restart.',\n  'Job execution interrupted: server shutdown.',\n  'Failed to clear queue and restart failed:',\n  'WebSocket failed to reconnect after restart:'\n]\nconst PREPROCESSING_FAILED_PREFIXES = [\n  'Preprocessing failed:',\n  'Failed to complete preparation:'\n]\n\nexport interface RuntimeErrorInfo {\n  exceptionType: string\n  exceptionMessage: string\n}\n\ninterface RuntimeCatalogMatch {\n  catalogId: string\n  params?: CatalogParams\n  detailsFallback?: string\n}\n\ninterface RuntimeMatchRule {\n  matches: (info: RuntimeErrorInfo, message: string) => boolean\n  resolve: (info: RuntimeErrorInfo, message: string) => RuntimeCatalogMatch\n}\n\nfunction catalogMatch(\n  catalogId: string,\n  options: Omit<RuntimeCatalogMatch, 'catalogId'> = {}\n): RuntimeCatalogMatch {\n  return { catalogId, ...options }\n}\n\nfunction catalogMatchWithMessageFallback(\n  catalogId: string,\n  message: string\n): RuntimeCatalogMatch {\n  return catalogMatch(catalogId, { detailsFallback: message })\n}\n\nfunction isOutOfMemoryError(info: RuntimeErrorInfo): boolean {\n  const message = info.exceptionMessage\n  return (\n    info.exceptionType === 'OOMError' ||\n    message.includes(CORE_OOM_TIP) ||\n    message.includes(CORE_OOM_ALLOCATION_PREFIX) ||\n    message.includes(CLOUD_OOM_PREFIX) ||\n    message.includes('CUDA out of memory') ||\n    message.includes('GPU out of memory')\n  )\n}\n\nfunction isImageNotLoadedError(\n  info: RuntimeErrorInfo,\n  message: string\n): boolean {\n  return (\n    info.exceptionType === 'ImageDownloadError' ||\n    (info.exceptionType === 'IsADirectoryError' &&\n      message.includes(ERRNO_DIRECTORY_MESSAGE))\n  )\n}\n\nfunction getSubscriptionUpgradeDetails(message: string): string {\n  return message.slice(SUBSCRIPTION_UPGRADE_REQUIRED_PREFIX.length).trim()\n}\n\nfunction isContentBlockedError(message: string): boolean {\n  return (\n    message.includes(GENERATED_VIDEO_REJECTED_MESSAGE) ||\n    message.includes(GENERATED_CONTENT_REJECTED_MESSAGE) ||\n    message.includes(SAFETY_CHECK_MESSAGE) ||\n    message.includes(CONTENT_POLICY_VIOLATION_MESSAGE) ||\n    message.startsWith(CONTENT_MODERATION_FLAGGED_PREFIX) ||\n    message.startsWith(GOOGLE_RAI_FILTERED_PREFIX) ||\n    message.startsWith(GOOGLE_RAI_BLOCKED_PREFIX)\n  )\n}\n\nfunction startsWithAny(message: string, prefixes: string[]): boolean {\n  return prefixes.some((prefix) => message.startsWith(prefix))\n}\n\nfunction hasEmbeddedApiErrorPayload(message: string): boolean {\n  // Embedded validation responses are parsed by a more specific path, so do not\n  // catalog them as a generic request failure here.\n  return /request returned error status \\d{3}:\\s*\\{/.test(message)\n}\n\nfunction isSubscriptionUpgradeMessage(message: string): boolean {\n  return (\n    message.toLowerCase().startsWith(SUBSCRIPTION_UPGRADE_REQUIRED_PREFIX) &&\n    getSubscriptionUpgradeDetails(message).length > 0\n  )\n}\n\n// Order matters: the first matching rule wins. Keep narrow user-actionable\n// signatures before broader fallbacks.\nconst RUNTIME_MATCH_RULES: RuntimeMatchRule[] = [\n  {\n    matches: isImageNotLoadedError,\n    resolve: (_info, message) =>\n      catalogMatchWithMessageFallback(IMAGE_NOT_LOADED_CATALOG_ID, message)\n  },\n  {\n    matches: isOutOfMemoryError,\n    resolve: (_info, message) =>\n      catalogMatchWithMessageFallback(OUT_OF_MEMORY_CATALOG_ID, message)\n  },\n  {\n    matches: (_info, message) => message.startsWith(INVALID_CLIP_INPUT_PREFIX),\n    resolve: (_info, message) =>\n      catalogMatchWithMessageFallback(INVALID_CLIP_INPUT_CATALOG_ID, message)\n  },\n  {\n    matches: (_info, message) =>\n      message.includes(PROMPT_TOO_SHORT_MESSAGE) ||\n      message.includes(PROMPT_EMPTY_MESSAGE),\n    resolve: () => catalogMatch(INVALID_PROMPT_CATALOG_ID)\n  },\n  {\n    matches: (info, message) =>\n      info.exceptionType === 'ValidationError' &&\n      INVALID_WORKFLOW_REQUEST_MESSAGES.has(message),\n    resolve: () => catalogMatch(INVALID_WORKFLOW_REQUEST_CATALOG_ID)\n  },\n  {\n    matches: (_info, message) =>\n      WORKSPACE_INSUFFICIENT_CREDITS_MESSAGES.has(message),\n    resolve: () => catalogMatch(WORKSPACE_INSUFFICIENT_CREDITS_CATALOG_ID)\n  },\n  {\n    // 'insufficient_credits' is the error.type BE-2866 will emit on the\n    // personal submit-time 402; the team submit path is a 429 matched by\n    // message in WORKSPACE_INSUFFICIENT_CREDITS_MESSAGES above.\n    matches: (info, message) =>\n      info.exceptionType === 'InsufficientFundsError' ||\n      info.exceptionType === 'insufficient_credits' ||\n      INSUFFICIENT_CREDITS_MESSAGES.has(message),\n    resolve: () => catalogMatch(INSUFFICIENT_CREDITS_CATALOG_ID)\n  },\n  {\n    matches: (info, message) =>\n      info.exceptionType === 'InactiveSubscriptionError' ||\n      SUBSCRIPTION_REQUIRED_MESSAGES.has(message),\n    resolve: () => catalogMatch(SUBSCRIPTION_REQUIRED_CATALOG_ID)\n  },\n  {\n    matches: (_info, message) => isSubscriptionUpgradeMessage(message),\n    resolve: (_info, message) => {\n      const modelNames = getSubscriptionUpgradeDetails(message)\n      return catalogMatch(SUBSCRIPTION_UPGRADE_REQUIRED_CATALOG_ID, {\n        params: { modelNames },\n        detailsFallback: message\n      })\n    }\n  },\n  {\n    matches: (info, message) =>\n      info.exceptionType === 'AccessRequired' ||\n      message === ACCESS_REQUIRED_MESSAGE,\n    resolve: () => catalogMatch(ACCESS_REQUIRED_CATALOG_ID)\n  },\n  {\n    matches: (info, message) =>\n      info.exceptionType === 'ModelAccessError' ||\n      message === MODEL_ACCESS_ERROR_MESSAGE,\n    resolve: () => catalogMatch(MODEL_ACCESS_ERROR_CATALOG_ID)\n  },\n  {\n    matches: (_info, message) => message.includes(SIGN_IN_REQUIRED_MESSAGE),\n    resolve: () => catalogMatch(SIGN_IN_REQUIRED_CATALOG_ID)\n  },\n  {\n    matches: (_info, message) => message.startsWith(RATE_LIMITED_PREFIX),\n    resolve: (_info, message) =>\n      catalogMatchWithMessageFallback(RATE_LIMITED_CATALOG_ID, message)\n  },\n  {\n    matches: (info, message) =>\n      info.exceptionType === 'PreprocessingTimeout' ||\n      PREPROCESSING_TIMEOUT_MESSAGES.has(message),\n    resolve: () => catalogMatch(PREPROCESSING_TIMEOUT_CATALOG_ID)\n  },\n  {\n    matches: (_info, message) =>\n      message === PREPROCESSING_FAILED_MESSAGE ||\n      startsWithAny(message, PREPROCESSING_FAILED_PREFIXES),\n    resolve: (_info, message) =>\n      message === PREPROCESSING_FAILED_MESSAGE\n        ? catalogMatch(PREPROCESSING_FAILED_CATALOG_ID)\n        : catalogMatchWithMessageFallback(\n            PREPROCESSING_FAILED_CATALOG_ID,\n            message\n          )\n  },\n  {\n    matches: (info, message) =>\n      info.exceptionType === 'PanicError' &&\n      message.startsWith(MODEL_DOWNLOAD_PANIC_PREFIX),\n    resolve: (_info, message) =>\n      catalogMatchWithMessageFallback(MODEL_DOWNLOAD_FAILED_CATALOG_ID, message)\n  },\n  {\n    matches: (_info, message) => isContentBlockedError(message),\n    resolve: (_info, message) =>\n      catalogMatchWithMessageFallback(CONTENT_BLOCKED_CATALOG_ID, message)\n  },\n  {\n    matches: (_info, message) => startsWithAny(message, START_FAILED_PREFIXES),\n    resolve: (_info, message) =>\n      catalogMatchWithMessageFallback(RUN_START_FAILED_CATALOG_ID, message)\n  },\n  {\n    matches: (_info, message) =>\n      startsWithAny(message, REQUEST_FAILED_PREFIXES) &&\n      !hasEmbeddedApiErrorPayload(message),\n    resolve: (_info, message) =>\n      catalogMatchWithMessageFallback(REQUEST_FAILED_CATALOG_ID, message)\n  },\n  {\n    matches: (_info, message) => message === RUN_START_FAILED_MESSAGE,\n    resolve: () => catalogMatch(RUN_START_FAILED_CATALOG_ID)\n  },\n  {\n    matches: (_info, message) => message === RUN_ENDED_UNEXPECTEDLY_MESSAGE,\n    resolve: () => catalogMatch(RUN_ENDED_UNEXPECTEDLY_CATALOG_ID)\n  },\n  {\n    matches: (info, message) =>\n      info.exceptionType === 'PanicError' &&\n      message.startsWith('panic during job execution:'),\n    resolve: (_info, message) =>\n      catalogMatchWithMessageFallback(\n        RUN_ENDED_UNEXPECTEDLY_CATALOG_ID,\n        message\n      )\n  },\n  {\n    matches: (_info, message) => TIMEOUT_MESSAGES.has(message),\n    resolve: () => catalogMatch(TIMEOUT_CATALOG_ID)\n  },\n  {\n    matches: (_info, message) => GENERATION_STALLED_MESSAGES.has(message),\n    resolve: () => catalogMatch(GENERATION_STALLED_CATALOG_ID)\n  },\n  {\n    matches: (_info, message) => SERVER_CRASHED_MESSAGES.has(message),\n    resolve: () => catalogMatch(SERVER_CRASHED_CATALOG_ID)\n  },\n  {\n    matches: (_info, message) =>\n      startsWithAny(message, SERVER_CRASHED_PREFIXES),\n    resolve: (_info, message) =>\n      catalogMatchWithMessageFallback(SERVER_CRASHED_CATALOG_ID, message)\n  },\n  {\n    matches: (_info, message) => SERVER_BUSY_MESSAGES.has(message),\n    resolve: () => catalogMatch(SERVER_BUSY_CATALOG_ID)\n  },\n  {\n    matches: (info, message) =>\n      info.exceptionType === 'UnexpectedServiceError' ||\n      message === UNEXPECTED_SERVICE_ERROR_MESSAGE,\n    resolve: () => catalogMatch(UNEXPECTED_SERVICE_ERROR_CATALOG_ID)\n  },\n  {\n    matches: (info, message) =>\n      message === REQUEST_FAILED_MESSAGE ||\n      (info.exceptionType === 'RequestError' &&\n        !hasEmbeddedApiErrorPayload(message)),\n    resolve: (_info, message) =>\n      message === REQUEST_FAILED_MESSAGE\n        ? catalogMatch(REQUEST_FAILED_CATALOG_ID)\n        : catalogMatchWithMessageFallback(REQUEST_FAILED_CATALOG_ID, message)\n  }\n]\n\nexport function resolveRuntimeCatalogMatch(\n  info: RuntimeErrorInfo\n): RuntimeCatalogMatch | undefined {\n  const message = info.exceptionMessage.trim()\n\n  for (const rule of RUNTIME_MATCH_RULES) {\n    if (rule.matches(info, message)) return rule.resolve(info, message)\n  }\n\n  return undefined\n}\n","import type { Component } from 'vue'\n\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nimport type {\n  SettingDialogProps,\n  SettingPanelType\n} from '@/platform/settings/types'\n\nconst DIALOG_KEY = 'global-settings'\n\n// The redesigned Settings dialog is 1280px wide (DES 3253-16079).\nlet settingDialogComponent: Component<SettingDialogProps> | undefined\n\n/**\n * The settings dialog subtree opens the settings dialog itself (billing\n * stores, top-up dialogs, confirmation content), so the composable cannot\n * import the component without an import cycle. The app shell registers it.\n */\nexport function registerSettingDialogComponent(\n  component: Component<SettingDialogProps>\n) {\n  settingDialogComponent = component\n}\n\nexport function useSettingsDialog() {\n  const dialogStore = useDialogStore()\n\n  function hide() {\n    dialogStore.closeDialog({ key: DIALOG_KEY })\n  }\n\n  function show(panel?: SettingPanelType, settingId?: string) {\n    if (!settingDialogComponent) {\n      reportError(new Error('Setting dialog component is not registered'), {\n        errorType: 'failure_opening_settings_dialog',\n        surface: 'platform'\n      })\n      return\n    }\n    dialogStore.showDialog({\n      key: DIALOG_KEY,\n      component: settingDialogComponent,\n      props: {\n        onClose: hide,\n        ...(panel ? { defaultPanel: panel } : {}),\n        ...(settingId ? { scrollToSettingId: settingId } : {})\n      },\n      dialogComponentProps: {\n        headless: true,\n        closable: true\n      }\n    })\n  }\n\n  function showAbout() {\n    show('about')\n  }\n\n  return { show, hide, showAbout }\n}\n","<template>\n  <section\n    class=\"m-2 mt-4 flex flex-col gap-6 wrap-break-word whitespace-pre-wrap\"\n  >\n    <div>\n      <span>{{ message }}</span>\n      <ul v-if=\"itemList?.length\" class=\"m-0 mt-2 flex flex-col gap-2 pl-4\">\n        <li v-for=\"item of itemList\" :key=\"item\">\n          {{ item }}\n        </li>\n      </ul>\n      <div\n        v-if=\"hint\"\n        role=\"status\"\n        class=\"mt-2 flex items-start gap-2 text-sm text-muted-foreground\"\n      >\n        <i class=\"pi pi-info-circle mt-0.5\" aria-hidden=\"true\" />\n        <span>{{ hint }}</span>\n      </div>\n    </div>\n    <div class=\"flex shrink-0 flex-wrap justify-end gap-4\">\n      <div\n        v-if=\"type === 'overwriteBlueprint'\"\n        class=\"flex flex-col justify-start gap-1\"\n      >\n        <div class=\"flex gap-4\">\n          <input\n            id=\"doNotAskAgain\"\n            v-model=\"doNotAskAgain\"\n            type=\"checkbox\"\n            class=\"size-4 cursor-pointer\"\n          />\n          <label for=\"doNotAskAgain\">{{\n            t('missingModelsDialog.doNotAskAgain')\n          }}</label>\n        </div>\n        <i18n-t\n          v-if=\"doNotAskAgain\"\n          keypath=\"missingModelsDialog.reEnableInSettings\"\n          tag=\"span\"\n          class=\"ml-8 text-sm text-muted-foreground\"\n        >\n          <template #link>\n            <Button\n              variant=\"textonly\"\n              class=\"cursor-pointer p-0 text-sm text-muted-foreground underline hover:bg-transparent\"\n              @click=\"openBlueprintOverwriteSetting\"\n            >\n              {{ t('missingModelsDialog.reEnableInSettingsLink') }}\n            </Button>\n          </template>\n        </i18n-t>\n      </div>\n\n      <Button\n        v-if=\"type !== 'info' && type !== 'dirtyClose'\"\n        variant=\"secondary\"\n        autofocus\n        @click=\"onCancel\"\n      >\n        <i class=\"pi pi-undo\" />\n        {{ $t('g.cancel') }}\n      </Button>\n      <Button v-if=\"type === 'default'\" variant=\"primary\" @click=\"onConfirm\">\n        <i class=\"pi pi-check\" />\n        {{ $t('g.confirm') }}\n      </Button>\n      <Button\n        v-else-if=\"type === 'delete'\"\n        variant=\"destructive\"\n        @click=\"onConfirm\"\n      >\n        <i class=\"pi pi-trash\" />\n        {{ $t('g.delete') }}\n      </Button>\n      <Button\n        v-else-if=\"type === 'overwrite' || type === 'overwriteBlueprint'\"\n        variant=\"destructive\"\n        @click=\"onConfirm\"\n      >\n        <i class=\"pi pi-save\" />\n        {{ $t('g.overwrite') }}\n      </Button>\n      <template v-else-if=\"type === 'dirtyClose'\">\n        <Button variant=\"secondary\" @click=\"onDeny\">\n          <i class=\"pi pi-times\" />\n          {{ denyLabel ?? $t('g.no') }}\n        </Button>\n        <Button autofocus @click=\"onConfirm\">\n          <i class=\"pi pi-save\" />\n          {{ $t('g.save') }}\n        </Button>\n      </template>\n      <Button\n        v-else-if=\"type === 'reinstall'\"\n        variant=\"destructive\"\n        @click=\"onConfirm\"\n      >\n        <i class=\"pi pi-eraser\" />\n        {{ $t('desktopMenu.reinstall') }}\n      </Button>\n      <!-- Info - just show an OK button -->\n      <Button v-else-if=\"type === 'info'\" variant=\"primary\" @click=\"onCancel\">\n        {{ $t('g.ok') }}\n      </Button>\n      <!-- Invalid - just show a close button. -->\n      <Button v-else variant=\"primary\" @click=\"onCancel\">\n        <i class=\"pi pi-times\" />\n        {{ $t('g.close') }}\n      </Button>\n    </div>\n  </section>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useSettingsDialog } from '@/platform/settings/composables/useSettingsDialog'\nimport type { ConfirmationDialogType } from '@/components/dialog/content/confirmationDialogTypes'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nconst props = defineProps<{\n  message: string\n  type: ConfirmationDialogType\n  onConfirm: (value?: boolean) => void\n  itemList?: string[]\n  hint?: string\n  denyLabel?: string\n}>()\n\nconst { t } = useI18n()\n\nconst onCancel = () => useDialogStore().closeDialog()\n\nfunction openBlueprintOverwriteSetting() {\n  useDialogStore().closeDialog()\n  useSettingsDialog().show(undefined, 'Comfy.Workflow.WarnBlueprintOverwrite')\n}\n\nconst doNotAskAgain = ref(false)\n\nconst onDeny = () => {\n  props.onConfirm(false)\n  useDialogStore().closeDialog()\n}\n\nconst onConfirm = () => {\n  if (props.type === 'overwriteBlueprint' && doNotAskAgain.value)\n    void useSettingStore().set('Comfy.Workflow.WarnBlueprintOverwrite', false)\n  props.onConfirm(true)\n  useDialogStore().closeDialog()\n}\n</script>\n","<template>\n  <section\n    class=\"m-2 mt-4 flex flex-col gap-6 wrap-break-word whitespace-pre-wrap\"\n  >\n    <div>\n      <span>{{ message }}</span>\n      <ul v-if=\"itemList?.length\" class=\"m-0 mt-2 flex flex-col gap-2 pl-4\">\n        <li v-for=\"item of itemList\" :key=\"item\">\n          {{ item }}\n        </li>\n      </ul>\n      <div\n        v-if=\"hint\"\n        role=\"status\"\n        class=\"mt-2 flex items-start gap-2 text-sm text-muted-foreground\"\n      >\n        <i class=\"pi pi-info-circle mt-0.5\" aria-hidden=\"true\" />\n        <span>{{ hint }}</span>\n      </div>\n    </div>\n    <div class=\"flex shrink-0 flex-wrap justify-end gap-4\">\n      <div\n        v-if=\"type === 'overwriteBlueprint'\"\n        class=\"flex flex-col justify-start gap-1\"\n      >\n        <div class=\"flex gap-4\">\n          <input\n            id=\"doNotAskAgain\"\n            v-model=\"doNotAskAgain\"\n            type=\"checkbox\"\n            class=\"size-4 cursor-pointer\"\n          />\n          <label for=\"doNotAskAgain\">{{\n            t('missingModelsDialog.doNotAskAgain')\n          }}</label>\n        </div>\n        <i18n-t\n          v-if=\"doNotAskAgain\"\n          keypath=\"missingModelsDialog.reEnableInSettings\"\n          tag=\"span\"\n          class=\"ml-8 text-sm text-muted-foreground\"\n        >\n          <template #link>\n            <Button\n              variant=\"textonly\"\n              class=\"cursor-pointer p-0 text-sm text-muted-foreground underline hover:bg-transparent\"\n              @click=\"openBlueprintOverwriteSetting\"\n            >\n              {{ t('missingModelsDialog.reEnableInSettingsLink') }}\n            </Button>\n          </template>\n        </i18n-t>\n      </div>\n\n      <Button\n        v-if=\"type !== 'info' && type !== 'dirtyClose'\"\n        variant=\"secondary\"\n        autofocus\n        @click=\"onCancel\"\n      >\n        <i class=\"pi pi-undo\" />\n        {{ $t('g.cancel') }}\n      </Button>\n      <Button v-if=\"type === 'default'\" variant=\"primary\" @click=\"onConfirm\">\n        <i class=\"pi pi-check\" />\n        {{ $t('g.confirm') }}\n      </Button>\n      <Button\n        v-else-if=\"type === 'delete'\"\n        variant=\"destructive\"\n        @click=\"onConfirm\"\n      >\n        <i class=\"pi pi-trash\" />\n        {{ $t('g.delete') }}\n      </Button>\n      <Button\n        v-else-if=\"type === 'overwrite' || type === 'overwriteBlueprint'\"\n        variant=\"destructive\"\n        @click=\"onConfirm\"\n      >\n        <i class=\"pi pi-save\" />\n        {{ $t('g.overwrite') }}\n      </Button>\n      <template v-else-if=\"type === 'dirtyClose'\">\n        <Button variant=\"secondary\" @click=\"onDeny\">\n          <i class=\"pi pi-times\" />\n          {{ denyLabel ?? $t('g.no') }}\n        </Button>\n        <Button autofocus @click=\"onConfirm\">\n          <i class=\"pi pi-save\" />\n          {{ $t('g.save') }}\n        </Button>\n      </template>\n      <Button\n        v-else-if=\"type === 'reinstall'\"\n        variant=\"destructive\"\n        @click=\"onConfirm\"\n      >\n        <i class=\"pi pi-eraser\" />\n        {{ $t('desktopMenu.reinstall') }}\n      </Button>\n      <!-- Info - just show an OK button -->\n      <Button v-else-if=\"type === 'info'\" variant=\"primary\" @click=\"onCancel\">\n        {{ $t('g.ok') }}\n      </Button>\n      <!-- Invalid - just show a close button. -->\n      <Button v-else variant=\"primary\" @click=\"onCancel\">\n        <i class=\"pi pi-times\" />\n        {{ $t('g.close') }}\n      </Button>\n    </div>\n  </section>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useSettingsDialog } from '@/platform/settings/composables/useSettingsDialog'\nimport type { ConfirmationDialogType } from '@/components/dialog/content/confirmationDialogTypes'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nconst props = defineProps<{\n  message: string\n  type: ConfirmationDialogType\n  onConfirm: (value?: boolean) => void\n  itemList?: string[]\n  hint?: string\n  denyLabel?: string\n}>()\n\nconst { t } = useI18n()\n\nconst onCancel = () => useDialogStore().closeDialog()\n\nfunction openBlueprintOverwriteSetting() {\n  useDialogStore().closeDialog()\n  useSettingsDialog().show(undefined, 'Comfy.Workflow.WarnBlueprintOverwrite')\n}\n\nconst doNotAskAgain = ref(false)\n\nconst onDeny = () => {\n  props.onConfirm(false)\n  useDialogStore().closeDialog()\n}\n\nconst onConfirm = () => {\n  if (props.type === 'overwriteBlueprint' && doNotAskAgain.value)\n    void useSettingStore().set('Comfy.Workflow.WarnBlueprintOverwrite', false)\n  props.onConfirm(true)\n  useDialogStore().closeDialog()\n}\n</script>\n","<template>\n  <div :class=\"cn('h-full p-8', props.class)\">\n    <div class=\"flex flex-col items-center bg-(--surface-ground) text-center\">\n      <i v-if=\"icon\" :class=\"cn(icon, 'mb-4 text-5xl')\" />\n      <h3 v-if=\"title\" class=\"mb-2 text-base-foreground\">{{ title }}</h3>\n      <p :class=\"cn('mb-4 text-center whitespace-pre-line', textClass)\">\n        {{ message }}\n      </p>\n      <Button\n        v-if=\"buttonLabel\"\n        :variant=\"buttonVariant ?? 'textonly'\"\n        @click=\"$emit('action')\"\n      >\n        <i v-if=\"buttonIcon\" :class=\"buttonIcon\" />\n        {{ buttonLabel }}\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport type { ButtonVariants } from '@comfyorg/design-system/button.variants'\n\nconst props = defineProps<{\n  class?: string\n  icon?: string\n  title?: string\n  message: string\n  textClass?: string\n  buttonIcon?: string\n  buttonLabel?: string\n  buttonVariant?: ButtonVariants['variant']\n}>()\n\ndefineEmits(['action'])\n</script>\n","<template>\n  <div :class=\"cn('h-full p-8', props.class)\">\n    <div class=\"flex flex-col items-center bg-(--surface-ground) text-center\">\n      <i v-if=\"icon\" :class=\"cn(icon, 'mb-4 text-5xl')\" />\n      <h3 v-if=\"title\" class=\"mb-2 text-base-foreground\">{{ title }}</h3>\n      <p :class=\"cn('mb-4 text-center whitespace-pre-line', textClass)\">\n        {{ message }}\n      </p>\n      <Button\n        v-if=\"buttonLabel\"\n        :variant=\"buttonVariant ?? 'textonly'\"\n        @click=\"$emit('action')\"\n      >\n        <i v-if=\"buttonIcon\" :class=\"buttonIcon\" />\n        {{ buttonLabel }}\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport type { ButtonVariants } from '@comfyorg/design-system/button.variants'\n\nconst props = defineProps<{\n  class?: string\n  icon?: string\n  title?: string\n  message: string\n  textClass?: string\n  buttonIcon?: string\n  buttonLabel?: string\n  buttonVariant?: ButtonVariants['variant']\n}>()\n\ndefineEmits(['action'])\n</script>\n","<template>\n  <Button\n    data-testid=\"error-dialog-find-issues\"\n    variant=\"secondary\"\n    @click=\"openGitHubIssues\"\n  >\n    <i class=\"pi pi-github\" />\n    {{ $t('g.findIssues') }}\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useTelemetry } from '@/platform/telemetry'\n\nconst props = defineProps<{\n  errorMessage: string\n  repoOwner: string\n  repoName: string\n}>()\n\nconst queryString = computed(() => props.errorMessage + ' is:issue')\n\nfunction openGitHubIssues() {\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'error_dialog_find_existing_issues_clicked',\n    element_group: 'error_dialog'\n  })\n  const query = encodeURIComponent(queryString.value)\n  const url = `https://github.com/${props.repoOwner}/${props.repoName}/issues?q=${query}`\n  window.open(url, '_blank')\n}\n</script>\n","<template>\n  <Button\n    data-testid=\"error-dialog-find-issues\"\n    variant=\"secondary\"\n    @click=\"openGitHubIssues\"\n  >\n    <i class=\"pi pi-github\" />\n    {{ $t('g.findIssues') }}\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useTelemetry } from '@/platform/telemetry'\n\nconst props = defineProps<{\n  errorMessage: string\n  repoOwner: string\n  repoName: string\n}>()\n\nconst queryString = computed(() => props.errorMessage + ' is:issue')\n\nfunction openGitHubIssues() {\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'error_dialog_find_existing_issues_clicked',\n    element_group: 'error_dialog'\n  })\n  const query = encodeURIComponent(queryString.value)\n  const url = `https://github.com/${props.repoOwner}/${props.repoName}/issues?q=${query}`\n  window.open(url, '_blank')\n}\n</script>\n","import { t, te } from '@/i18n'\n\n// Shared i18n helpers for error catalog resolvers. These preserve the raw API\n// message/details as fallbacks when a catalog key is not available. Keep this\n// module folder-internal so UI code only consumes resolved display fields.\nexport interface ErrorResolveContext {\n  isCloud?: boolean\n  nodeDisplayName?: string\n}\n\nexport type CatalogParams = Record<string, string | number>\n\nexport function translateCatalogMessage(\n  key: string,\n  fallback: string,\n  params?: CatalogParams\n): string {\n  if (te(key))\n    return params ? t(key, params, { escapeParameter: false }) : t(key)\n  if (!params) return fallback\n\n  return fallback.replace(/\\{(\\w+)\\}/g, (match, paramName) => {\n    const value: unknown = params[paramName]\n    return value === undefined ? match : String(value)\n  })\n}\n\nexport function translateOptionalCatalogMessage(\n  key: string,\n  fallback?: string,\n  params?: CatalogParams\n): string | undefined {\n  if (te(key))\n    return params ? t(key, params, { escapeParameter: false }) : t(key)\n  return fallback?.trim() ? fallback : undefined\n}\n\nexport function normalizeNodeName(nodeDisplayName: string | undefined): string {\n  return (\n    nodeDisplayName?.trim() ||\n    translateCatalogMessage('errorCatalog.fallbacks.nodeName', 'This node')\n  )\n}\n","import type { ResolvedCatalogErrorMessage } from './types'\n\nimport {\n  normalizeNodeName,\n  translateCatalogMessage,\n  translateOptionalCatalogMessage\n} from './catalogI18n'\nimport type { CatalogParams, ErrorResolveContext } from './catalogI18n'\n\n// Builds resolved display fields while callers keep the raw API message/details\n// on the ErrorItem.\nexport function resolveRuntimeCatalogCopy(\n  catalogId: string,\n  fallbackMessage: string,\n  context: ErrorResolveContext,\n  options: {\n    includeItemLabel?: boolean\n    includeToast?: boolean\n    params?: CatalogParams\n    detailsFallback?: string\n  } = {}\n): ResolvedCatalogErrorMessage {\n  const keyPrefix = `errorCatalog.runtimeErrors.${catalogId}`\n  const nodeName = normalizeNodeName(context.nodeDisplayName)\n  const params = { nodeName, ...options.params }\n  const resolveMessage = (suffix: string, fallback = fallbackMessage) =>\n    translateCatalogMessage(`${keyPrefix}.${suffix}`, fallback, params)\n\n  const displayMessage = resolveMessage('message')\n  const result: ResolvedCatalogErrorMessage = {\n    catalogId,\n    displayTitle: resolveMessage('title'),\n    displayMessage\n  }\n\n  if (options.includeToast !== false) {\n    result.toastTitle = resolveMessage('toastTitle')\n    result.toastMessage = resolveMessage('toastMessage')\n  }\n\n  const displayDetails = translateOptionalCatalogMessage(\n    `${keyPrefix}.details`,\n    options.detailsFallback,\n    params\n  )\n  if (displayDetails) result.displayDetails = displayDetails\n\n  if (options.includeItemLabel) {\n    result.displayItemLabel = resolveMessage('itemLabel', nodeName)\n  }\n\n  return result\n}\n","import type {\n  ResolvedCatalogErrorMessage,\n  RunErrorMessageSource\n} from './types'\n\nimport { EXECUTION_FAILED_CATALOG_ID } from './catalogIds'\nimport type { ErrorResolveContext } from './catalogI18n'\nimport { resolveRuntimeCatalogCopy } from './runtimeErrorCopy'\nimport { resolveRuntimeCatalogMatch } from './runtimeErrorMatcher'\n\ntype ExecutionErrorResolveContext = Pick<ErrorResolveContext, 'nodeDisplayName'>\n\n// Resolves node-scoped runtime failures while preserving raw API fields.\nexport function resolveExecutionErrorMessage(\n  error: Extract<RunErrorMessageSource, { kind: 'execution' }>['error'],\n  context: ExecutionErrorResolveContext\n): ResolvedCatalogErrorMessage {\n  const exceptionMessage = error.exception_message.trim()\n  const match = resolveRuntimeCatalogMatch({\n    exceptionType: error.exception_type,\n    exceptionMessage\n  })\n  if (!match) {\n    return resolveRuntimeCatalogCopy(\n      EXECUTION_FAILED_CATALOG_ID,\n      error.exception_message,\n      context,\n      { includeItemLabel: true }\n    )\n  }\n\n  return resolveRuntimeCatalogCopy(\n    match.catalogId,\n    error.exception_message,\n    context,\n    {\n      includeItemLabel: true,\n      params: match.params,\n      detailsFallback: match.detailsFallback\n    }\n  )\n}\n","import type { ResolvedErrorMessage, RunErrorMessageSource } from './types'\n\nimport type { ErrorResolveContext } from './catalogI18n'\nimport { translateCatalogMessage } from './catalogI18n'\nimport { resolveRuntimeCatalogCopy } from './runtimeErrorCopy'\nimport { resolveRuntimeCatalogMatch } from './runtimeErrorMatcher'\nimport { st } from '@/i18n'\n\n// Resolves prompt-level errors and non-node-scoped failures before falling\n// back to prompt-specific catalog keys.\nconst KNOWN_PROMPT_ERROR_TYPES = new Set([\n  'prompt_no_outputs',\n  'no_prompt',\n  'server_error',\n  'missing_node_type',\n  'prompt_outputs_failed_validation',\n  'agent_api_failed',\n  'op_rejected',\n  'prefix_abort',\n  'guard_trip',\n  'apply_failed'\n])\n\nfunction getPromptExceptionMessage(\n  error: Extract<RunErrorMessageSource, { kind: 'prompt' }>['error']\n): string {\n  const message = error.message.trim()\n  const prefixedType = `${error.type}: `\n  return message.startsWith(prefixedType)\n    ? message.slice(prefixedType.length).trim()\n    : message\n}\n\nexport function resolvePromptErrorMessage(\n  error: Extract<RunErrorMessageSource, { kind: 'prompt' }>['error'],\n  context: ErrorResolveContext\n): ResolvedErrorMessage {\n  const promptExceptionMessage = getPromptExceptionMessage(error)\n  const runtimeMatch = resolveRuntimeCatalogMatch({\n    exceptionType: error.type,\n    exceptionMessage: promptExceptionMessage\n  })\n  if (runtimeMatch) {\n    // Leave toast copy to node-scoped errors where a node-specific\n    // action/message is safe.\n    return resolveRuntimeCatalogCopy(\n      runtimeMatch.catalogId,\n      promptExceptionMessage || error.message,\n      context,\n      {\n        includeToast: false,\n        params: runtimeMatch.params,\n        detailsFallback: runtimeMatch.detailsFallback\n      }\n    )\n  }\n\n  if (!KNOWN_PROMPT_ERROR_TYPES.has(error.type)) return {}\n\n  const errorTypeKey =\n    error.type === 'server_error'\n      ? context.isCloud\n        ? 'server_error_cloud'\n        : 'server_error_local'\n      : error.type\n\n  return {\n    displayTitle: translateCatalogMessage(\n      `errorCatalog.promptErrors.${errorTypeKey}.title`,\n      error.message\n    ),\n    displayMessage: st(\n      `errorCatalog.promptErrors.${errorTypeKey}.desc`,\n      error.message\n    )\n  }\n}\n","import type { NodeValidationError, ResolvedCatalogErrorMessage } from './types'\n\nimport {\n  IMAGE_NOT_LOADED_CATALOG_ID,\n  MISSING_CONNECTION_CATALOG_ID,\n  UNKNOWN_VALIDATION_ERROR_CATALOG_ID\n} from './catalogIds'\nimport {\n  normalizeNodeName,\n  translateCatalogMessage,\n  translateOptionalCatalogMessage\n} from './catalogI18n'\nimport type { CatalogParams, ErrorResolveContext } from './catalogI18n'\nimport {\n  INPUT_LEVEL_VALIDATION_ERROR_TYPES,\n  NODE_LEVEL_VALIDATION_ERROR_TYPES,\n  getInputConfigBounds,\n  isImageNotLoadedValidationError\n} from '@/utils/executionErrorUtil'\n\nconst REQUIRED_INPUT_MISSING_TYPE = 'required_input_missing'\n\n// Resolves node validation errors. Most validation types map 1:1 to their\n// catalog/locale keys; FE-specific recategorization uses a separate catalogId,\n// such as required_input_missing -> missing_connection.\ninterface ValidationCatalogRule {\n  catalogId: string\n  itemLabel: 'node' | 'nodeInput'\n  copyKeys?: CopyKeys\n}\n\ninterface CopyKeys {\n  detailsKey: string\n  toastMessageKey: string\n}\n\nconst DEFAULT_COPY_KEYS: CopyKeys = {\n  detailsKey: 'details',\n  toastMessageKey: 'toastMessage'\n}\n\nconst VALUE_SPECIFIC_COPY_RULES: Record<\n  string,\n  {\n    requiredParams: string[]\n    suffix: 'WithTypes' | 'WithValue'\n  }\n> = {\n  return_type_mismatch: {\n    requiredParams: ['expectedType', 'receivedType'],\n    suffix: 'WithTypes'\n  },\n  invalid_input_type: {\n    requiredParams: ['receivedValue', 'expectedType'],\n    suffix: 'WithValue'\n  },\n  value_smaller_than_min: {\n    requiredParams: ['receivedValue', 'minValue'],\n    suffix: 'WithValue'\n  },\n  value_bigger_than_max: {\n    requiredParams: ['receivedValue', 'maxValue'],\n    suffix: 'WithValue'\n  },\n  value_not_in_list: {\n    requiredParams: ['receivedValue'],\n    suffix: 'WithValue'\n  }\n}\n\ntype ValueSpecificCopyRule = (typeof VALUE_SPECIFIC_COPY_RULES)[string]\n\nconst NODE_LEVEL_VALIDATION_ERROR_RULES: Record<string, ValidationCatalogRule> =\n  Object.fromEntries(\n    Array.from(NODE_LEVEL_VALIDATION_ERROR_TYPES, (type) => [\n      type,\n      { catalogId: type, itemLabel: 'node' } satisfies ValidationCatalogRule\n    ])\n  )\n\nconst INPUT_LEVEL_VALIDATION_ERROR_RULES: Record<\n  string,\n  ValidationCatalogRule\n> = Object.fromEntries(\n  Array.from(INPUT_LEVEL_VALIDATION_ERROR_TYPES, (type) => [\n    type,\n    { catalogId: type, itemLabel: 'nodeInput' } satisfies ValidationCatalogRule\n  ])\n)\n\nconst VALIDATION_ERROR_RULES: Record<string, ValidationCatalogRule> = {\n  ...INPUT_LEVEL_VALIDATION_ERROR_RULES,\n  [REQUIRED_INPUT_MISSING_TYPE]: {\n    catalogId: MISSING_CONNECTION_CATALOG_ID,\n    itemLabel: 'nodeInput'\n  },\n  ...NODE_LEVEL_VALIDATION_ERROR_RULES\n}\n\n// Image-not-loaded shares the custom_validation_failed type, so type-keyed\n// dispatch cannot distinguish it. The override also keeps it on default copy\n// keys instead of custom_validation_failed's raw-details variant.\nconst IMAGE_NOT_LOADED_VALIDATION_RULE = {\n  catalogId: IMAGE_NOT_LOADED_CATALOG_ID,\n  itemLabel: 'node',\n  copyKeys: DEFAULT_COPY_KEYS\n} satisfies ValidationCatalogRule\n\nconst UNKNOWN_VALIDATION_ERROR_RULE = {\n  catalogId: UNKNOWN_VALIDATION_ERROR_CATALOG_ID,\n  itemLabel: 'node'\n} satisfies ValidationCatalogRule\n\nfunction getInputName(error: NodeValidationError): string {\n  const inputName = error.extra_info?.input_name\n  return (\n    inputName?.trim() ||\n    translateCatalogMessage('errorCatalog.fallbacks.inputName', 'unknown input')\n  )\n}\n\nfunction nodeInputItemLabel(nodeName: string, inputName: string): string {\n  return `${nodeName} - ${inputName}`\n}\n\nfunction formatDependencyCycleDetails(details: string): string {\n  // Dependency cycle paths may be reported as \"node -> node\"; catalog copy\n  // embeds those paths in prose, where \"to\" reads more naturally.\n  return details.replace(/\\s*->\\s*/g, ' to ')\n}\n\nfunction formatCatalogValue(value: unknown): string | undefined {\n  if (value === undefined || value === null) return undefined\n  if (typeof value === 'string') return value\n  if (typeof value === 'number' || typeof value === 'boolean') {\n    return String(value)\n  }\n\n  try {\n    return JSON.stringify(value)\n  } catch {\n    return undefined\n  }\n}\n\nfunction getInputConfigValue(\n  error: NodeValidationError,\n  key: 'min' | 'max'\n): string | undefined {\n  return formatCatalogValue(getInputConfigBounds(error)[key])\n}\n\nfunction getInputConfigType(error: NodeValidationError): string | undefined {\n  const inputConfig = error.extra_info?.input_config\n  if (!Array.isArray(inputConfig)) return undefined\n\n  return formatCatalogValue(inputConfig[0])\n}\n\nfunction getValidationParams(\n  error: NodeValidationError,\n  nodeName: string,\n  inputName: string\n): CatalogParams {\n  const params: CatalogParams = { nodeName, inputName }\n  const receivedValue = formatCatalogValue(error.extra_info?.received_value)\n  const receivedType = formatCatalogValue(error.extra_info?.received_type)\n  const expectedType = getInputConfigType(error)\n  const minValue = getInputConfigValue(error, 'min')\n  const maxValue = getInputConfigValue(error, 'max')\n\n  if (receivedValue !== undefined) params.receivedValue = receivedValue\n  if (receivedType !== undefined) params.receivedType = receivedType\n  if (expectedType !== undefined) params.expectedType = expectedType\n  if (minValue !== undefined) params.minValue = minValue\n  if (maxValue !== undefined) params.maxValue = maxValue\n\n  return params\n}\n\nfunction hasParams(params: CatalogParams, keys: string[]): boolean {\n  return keys.every((key) => Object.hasOwn(params, key))\n}\n\nfunction getValueSpecificCopyKeys(\n  errorType: string,\n  params: CatalogParams\n): CopyKeys {\n  const rule = getValueSpecificRule(errorType)\n  if (!rule || !hasParams(params, rule.requiredParams)) return DEFAULT_COPY_KEYS\n\n  return {\n    detailsKey: `details${rule.suffix}`,\n    toastMessageKey: `toastMessage${rule.suffix}`\n  }\n}\n\nfunction getValueSpecificRule(\n  errorType: string\n): ValueSpecificCopyRule | undefined {\n  return VALUE_SPECIFIC_COPY_RULES[errorType]\n}\n\nfunction getRawDetailsCopyKeys(error: NodeValidationError): CopyKeys {\n  return error.details?.trim()\n    ? {\n        detailsKey: 'detailsWithRawDetails',\n        toastMessageKey: 'toastMessageWithRawDetails'\n      }\n    : DEFAULT_COPY_KEYS\n}\n\nfunction getRawDetailsOnlyCopyKeys(error: NodeValidationError): CopyKeys {\n  if (!error.details?.trim()) return DEFAULT_COPY_KEYS\n\n  return {\n    detailsKey: 'detailsWithRawDetails',\n    toastMessageKey: 'toastMessage'\n  }\n}\n\nfunction getValidationCopyKeys(\n  error: NodeValidationError,\n  params: CatalogParams\n): CopyKeys {\n  if (\n    error.type === 'exception_during_validation' ||\n    error.type === 'exception_during_inner_validation'\n  ) {\n    return getRawDetailsCopyKeys(error)\n  }\n\n  if (error.type === 'custom_validation_failed') {\n    return getRawDetailsOnlyCopyKeys(error)\n  }\n\n  if (error.type === 'dependency_cycle') {\n    return getRawDetailsOnlyCopyKeys(error)\n  }\n\n  return getValueSpecificCopyKeys(error.type, params)\n}\n\nfunction resolveValidationCatalogCopy(\n  error: NodeValidationError,\n  context: ErrorResolveContext,\n  localeKey: string,\n  rule: ValidationCatalogRule\n): ResolvedCatalogErrorMessage {\n  const nodeName = normalizeNodeName(context.nodeDisplayName)\n  const inputName = getInputName(error)\n  const trimmedDetails = error.details?.trim() ?? ''\n  const rawDetails =\n    error.type === 'dependency_cycle'\n      ? formatDependencyCycleDetails(trimmedDetails)\n      : trimmedDetails\n  const params = {\n    ...getValidationParams(error, nodeName, inputName),\n    errorType: error.type || 'unknown',\n    rawDetails\n  }\n  const keyPrefix = `errorCatalog.validationErrors.${localeKey}`\n  const titleFallback = error.message || error.type\n  const itemLabelFallback =\n    rule.itemLabel === 'node'\n      ? nodeName\n      : nodeInputItemLabel(nodeName, inputName)\n  const copyKeys = rule.copyKeys ?? getValidationCopyKeys(error, params)\n\n  return {\n    catalogId: rule.catalogId,\n    displayTitle: translateCatalogMessage(\n      `${keyPrefix}.title`,\n      titleFallback,\n      params\n    ),\n    displayMessage: translateCatalogMessage(\n      `${keyPrefix}.message`,\n      error.message,\n      params\n    ),\n    displayDetails: translateOptionalCatalogMessage(\n      `${keyPrefix}.${copyKeys.detailsKey}`,\n      error.details,\n      params\n    ),\n    displayItemLabel: translateCatalogMessage(\n      `${keyPrefix}.itemLabel`,\n      itemLabelFallback,\n      params\n    ),\n    toastTitle: translateCatalogMessage(\n      `${keyPrefix}.toastTitle`,\n      titleFallback,\n      params\n    ),\n    toastMessage: translateCatalogMessage(\n      `${keyPrefix}.${copyKeys.toastMessageKey}`,\n      error.message,\n      params\n    )\n  }\n}\n\nexport function resolveNodeValidationErrorMessage(\n  error: NodeValidationError,\n  context: ErrorResolveContext\n): ResolvedCatalogErrorMessage {\n  if (isImageNotLoadedValidationError(error)) {\n    return resolveValidationCatalogCopy(\n      error,\n      context,\n      'image_not_loaded',\n      IMAGE_NOT_LOADED_VALIDATION_RULE\n    )\n  }\n\n  const rule = getValidationRule(error.type)\n  if (!rule) {\n    return resolveValidationCatalogCopy(\n      error,\n      context,\n      'unknown_validation_error',\n      {\n        ...UNKNOWN_VALIDATION_ERROR_RULE,\n        copyKeys: getRawDetailsOnlyCopyKeys(error)\n      }\n    )\n  }\n\n  return resolveValidationCatalogCopy(error, context, error.type, rule)\n}\n\nfunction getValidationRule(type: string): ValidationCatalogRule | undefined {\n  return VALIDATION_ERROR_RULES[type]\n}\n","import { sumBy } from 'es-toolkit'\n\nimport type { MissingMediaGroup, MissingMediaViewModel } from './types'\n\ninterface MissingMediaReference {\n  mediaItem: MissingMediaViewModel\n  nodeRef: MissingMediaViewModel['referencingNodes'][number]\n}\n\nexport function getMissingMediaReferences(\n  groups: MissingMediaGroup[]\n): MissingMediaReference[] {\n  return groups.flatMap((group) =>\n    group.items.flatMap((mediaItem) =>\n      mediaItem.referencingNodes.map((nodeRef) => ({ mediaItem, nodeRef }))\n    )\n  )\n}\n\nexport function countMissingMediaReferences(\n  groups: MissingMediaGroup[]\n): number {\n  return sumBy(groups, (group) =>\n    sumBy(group.items, (item) => item.referencingNodes.length)\n  )\n}\n","import { sumBy } from 'es-toolkit'\n\nimport type {\n  MissingModelCandidate,\n  MissingModelGroup,\n  MissingModelViewModel\n} from '@/platform/missingModel/types'\n\nconst UNSUPPORTED = Symbol('unsupported')\n\nexport function countMissingModels(groups: MissingModelGroup[]): number {\n  return sumBy(groups, (group) => group.models.length)\n}\n\nexport function groupMissingModelCandidates(\n  candidates: MissingModelCandidate[] | null | undefined,\n  isCloud: boolean\n): MissingModelGroup[] {\n  if (!candidates?.length) return []\n\n  type GroupKey = string | null | typeof UNSUPPORTED\n  const map = new Map<\n    GroupKey,\n    { candidates: MissingModelCandidate[]; isAssetSupported: boolean }\n  >()\n\n  for (const candidate of candidates) {\n    const groupKey: GroupKey =\n      candidate.isAssetSupported || !isCloud\n        ? candidate.directory || null\n        : UNSUPPORTED\n    const existing = map.get(groupKey)\n    if (existing) {\n      existing.candidates.push(candidate)\n    } else {\n      map.set(groupKey, {\n        candidates: [candidate],\n        isAssetSupported: candidate.isAssetSupported\n      })\n    }\n  }\n\n  return Array.from(map.entries())\n    .sort(([dirA], [dirB]) => {\n      if (dirA === UNSUPPORTED) return 1\n      if (dirB === UNSUPPORTED) return -1\n      if (dirA === null) return 1\n      if (dirB === null) return -1\n      return dirA.localeCompare(dirB)\n    })\n    .map(([key, { candidates: groupCandidates, isAssetSupported }]) => ({\n      directory: typeof key === 'string' ? key : null,\n      models: groupCandidatesByName(groupCandidates),\n      isAssetSupported\n    }))\n}\n\nfunction groupCandidatesByName(\n  candidates: MissingModelCandidate[]\n): MissingModelViewModel[] {\n  const map = new Map<string, MissingModelViewModel>()\n  for (const c of candidates) {\n    const existing = map.get(c.name)\n    if (existing) {\n      if (c.nodeId) {\n        existing.referencingNodes.push({\n          nodeId: c.nodeId,\n          widgetName: c.widgetName\n        })\n      }\n    } else {\n      map.set(c.name, {\n        name: c.name,\n        representative: c,\n        referencingNodes: c.nodeId\n          ? [{ nodeId: c.nodeId, widgetName: c.widgetName }]\n          : []\n      })\n    }\n  }\n  return Array.from(map.values())\n}\n","import type {\n  MissingErrorMessageSource,\n  ResolvedMissingErrorMessage\n} from './types'\nimport { normalizeNodeName, translateCatalogMessage } from './catalogI18n'\nimport { countMissingMediaReferences } from '@/platform/missingMedia/missingMediaGrouping'\nimport { countMissingModels } from '@/platform/missingModel/missingModelGrouping'\nimport { st } from '@/i18n'\n\nfunction formatNodeTypeName(nodeType: string): string | null {\n  const trimmed = nodeType.trim()\n  if (!trimmed) return null\n\n  return trimmed\n    .replace(/[_-]+/g, ' ')\n    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2')\n    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')\n    .replace(/\\s+/g, ' ')\n    .trim()\n}\n\ntype NodeTypeErrorSource = Extract<\n  MissingErrorMessageSource,\n  { kind: 'missing_node' | 'swap_nodes' }\n>\ntype NodeTypeErrorItem = NodeTypeErrorSource['nodeTypes'][number]\n\nfunction getNodeTypeLabel(nodeType: NodeTypeErrorItem): string {\n  return typeof nodeType === 'string' ? nodeType : nodeType.type\n}\n\nfunction getDistinctNodeTypeLabels(nodeTypes: NodeTypeErrorItem[]): string[] {\n  const labels = new Set<string>()\n  for (const nodeType of nodeTypes) labels.add(getNodeTypeLabel(nodeType))\n  return Array.from(labels)\n}\n\ntype MissingNodeSource = Extract<\n  MissingErrorMessageSource,\n  { kind: 'missing_node' }\n>\n\nfunction isMissingNodeType(nodeType: NodeTypeErrorItem): boolean {\n  return typeof nodeType === 'string' || !nodeType.isReplaceable\n}\n\nfunction resolveMissingNodeDisplayMessage(source: MissingNodeSource): string {\n  const key = source.isCloud\n    ? 'errorCatalog.missingErrors.missing_node.displayMessageCloud'\n    : 'errorCatalog.missingErrors.missing_node.displayMessageOss'\n  const fallback = source.isCloud\n    ? \"Required custom nodes aren't supported on Cloud. Replace them with supported nodes.\"\n    : 'Install missing packs to use this workflow.'\n  return translateCatalogMessage(key, fallback)\n}\n\nfunction resolveMissingNodeToastTitle(source: MissingNodeSource): string {\n  const labels = getDistinctNodeTypeLabels(\n    source.nodeTypes.filter(isMissingNodeType)\n  )\n  const [firstLabel] = labels\n  if (labels.length === 1 && firstLabel) {\n    const key = source.isCloud\n      ? 'errorCatalog.missingErrors.missing_node.toastTitleOneCloud'\n      : 'errorCatalog.missingErrors.missing_node.toastTitleOneOss'\n    const fallback = source.isCloud\n      ? \"{nodeType} isn't available on Cloud\"\n      : 'Missing node: {nodeType}'\n    return translateCatalogMessage(key, fallback, { nodeType: firstLabel })\n  }\n\n  const key = source.isCloud\n    ? 'errorCatalog.missingErrors.missing_node.toastTitleManyCloud'\n    : 'errorCatalog.missingErrors.missing_node.toastTitleManyOss'\n  const fallback = source.isCloud\n    ? \"Nodes aren't available on Cloud\"\n    : 'Missing nodes'\n  return translateCatalogMessage(key, fallback)\n}\n\nfunction resolveMissingNodeToastMessage(source: MissingNodeSource): string {\n  const labels = getDistinctNodeTypeLabels(\n    source.nodeTypes.filter(isMissingNodeType)\n  )\n  const count = labels.length || source.count\n\n  if (count === 1) {\n    const key = source.isCloud\n      ? 'errorCatalog.missingErrors.missing_node.toastMessageOneCloud'\n      : 'errorCatalog.missingErrors.missing_node.toastMessageOneOss'\n    const fallback = source.isCloud\n      ? \"This node isn't supported on Cloud.\"\n      : \"This workflow uses a custom node that isn't installed. Install it from the registry or replace the node.\"\n    return translateCatalogMessage(key, fallback)\n  }\n\n  const key = source.isCloud\n    ? 'errorCatalog.missingErrors.missing_node.toastMessageManyCloud'\n    : 'errorCatalog.missingErrors.missing_node.toastMessageManyOss'\n  const fallback = source.isCloud\n    ? \"This workflow uses nodes that aren't supported on Cloud.\"\n    : '{count} nodes require missing node packs.'\n  return translateCatalogMessage(key, fallback, { count })\n}\n\ntype SwapNodeSource = Extract<MissingErrorMessageSource, { kind: 'swap_nodes' }>\n\nfunction isSwapNodeType(nodeType: NodeTypeErrorItem): nodeType is Exclude<\n  NodeTypeErrorItem,\n  string\n> & {\n  isReplaceable: true\n} {\n  return typeof nodeType !== 'string' && nodeType.isReplaceable === true\n}\n\nfunction getSwapNodeTypes(source: SwapNodeSource) {\n  return source.nodeTypes.filter(isSwapNodeType)\n}\n\nfunction resolveSwapNodeToastTitle(source: SwapNodeSource): string {\n  const nodeTypes = getSwapNodeTypes(source)\n  const labels = getDistinctNodeTypeLabels(nodeTypes)\n  const [firstLabel] = labels\n  if (labels.length === 1 && firstLabel) {\n    return translateCatalogMessage(\n      'errorCatalog.missingErrors.swap_nodes.toastTitleOne',\n      '{nodeType} can be replaced',\n      { nodeType: firstLabel }\n    )\n  }\n\n  return translateCatalogMessage(\n    'errorCatalog.missingErrors.swap_nodes.toastTitleMany',\n    'Nodes can be replaced'\n  )\n}\n\nfunction resolveSwapNodeToastMessage(source: SwapNodeSource): string {\n  const nodeTypes = getSwapNodeTypes(source)\n  const labels = getDistinctNodeTypeLabels(nodeTypes)\n  const [firstNodeType] = nodeTypes\n  if (labels.length === 1 && firstNodeType.replacement?.new_node_id) {\n    return translateCatalogMessage(\n      'errorCatalog.missingErrors.swap_nodes.toastMessageOne',\n      'Replace it with {replacementNodeType} from the error panel.',\n      { replacementNodeType: firstNodeType.replacement.new_node_id }\n    )\n  }\n\n  return translateCatalogMessage(\n    'errorCatalog.missingErrors.swap_nodes.toastMessageMany',\n    '{count} node types can be replaced with compatible alternatives.',\n    { count: labels.length || source.count }\n  )\n}\n\nfunction resolveSwapNodeDisplayMessage(): string {\n  return translateCatalogMessage(\n    'errorCatalog.missingErrors.swap_nodes.displayMessage',\n    'Some nodes can be replaced with alternatives'\n  )\n}\n\ntype MissingModelSource = Extract<\n  MissingErrorMessageSource,\n  { kind: 'missing_model' }\n>\n\nfunction getMissingModelCount(source: MissingModelSource): number {\n  return countMissingModels(source.groups) || source.count\n}\n\nfunction resolveMissingModelDisplayMessage(source: MissingModelSource): string {\n  const key = source.isCloud\n    ? 'errorCatalog.missingErrors.missing_model.displayMessageCloud'\n    : 'errorCatalog.missingErrors.missing_model.displayMessageOss'\n  const fallback = source.isCloud\n    ? 'Import a model, or open the node to replace it.'\n    : 'Download a model, or open the node to replace it.'\n  return translateCatalogMessage(key, fallback)\n}\n\nfunction resolveMissingModelToastTitle(source: MissingModelSource): string {\n  const firstModel = source.groups.flatMap((group) => group.models).at(0)\n  const count = getMissingModelCount(source)\n\n  if (count === 1 && firstModel) {\n    const key = source.isCloud\n      ? 'errorCatalog.missingErrors.missing_model.toastTitleOneCloud'\n      : 'errorCatalog.missingErrors.missing_model.toastTitleOneOss'\n    const fallback = source.isCloud\n      ? \"{modelName} isn't available on Cloud\"\n      : '{modelName} is missing'\n    return translateCatalogMessage(key, fallback, {\n      modelName: firstModel.name\n    })\n  }\n\n  const useCloudPluralTitle = source.isCloud && count > 1\n  const key = useCloudPluralTitle\n    ? 'errorCatalog.missingErrors.missing_model.toastTitleManyCloud'\n    : 'errorCatalog.missingErrors.missing_model.toastTitleMany'\n  const fallback = useCloudPluralTitle\n    ? \"Models aren't available on Cloud\"\n    : 'Missing models'\n  return translateCatalogMessage(key, fallback)\n}\n\nfunction getMissingModelNodeName(\n  model: MissingModelSource['groups'][number]['models'][number]\n): string {\n  return (\n    formatNodeTypeName(model.representative.nodeType) ??\n    translateCatalogMessage('errorCatalog.fallbacks.nodeName', 'This node')\n  )\n}\n\nfunction resolveMissingModelToastMessage(source: MissingModelSource): string {\n  const firstModel = source.groups.flatMap((group) => group.models).at(0)\n  const count = getMissingModelCount(source)\n\n  if (!firstModel || count !== 1) {\n    const key = source.isCloud\n      ? 'errorCatalog.missingErrors.missing_model.toastMessageManyCloud'\n      : 'errorCatalog.missingErrors.missing_model.toastMessageManyOss'\n    const fallback = source.isCloud\n      ? \"Some models aren't supported. Choose different ones.\"\n      : '{count} model files are missing.'\n    return translateCatalogMessage(key, fallback, { count })\n  }\n\n  if (source.isCloud) {\n    return translateCatalogMessage(\n      'errorCatalog.missingErrors.missing_model.toastMessageOneCloud',\n      \"This model isn't supported. Choose a different one.\"\n    )\n  }\n\n  return translateCatalogMessage(\n    'errorCatalog.missingErrors.missing_model.toastMessageOneOss',\n    '{nodeName} is missing a required model file.',\n    { nodeName: getMissingModelNodeName(firstModel) }\n  )\n}\n\ntype MissingMediaSource = Extract<\n  MissingErrorMessageSource,\n  { kind: 'missing_media' }\n>\n\ninterface MissingMediaItemLabelSource {\n  nodeDisplayName?: string\n  nodeType?: string\n  widgetName?: string\n}\n\nfunction getMissingMediaItems(source: MissingMediaSource) {\n  return source.groups.flatMap((group) => group.items)\n}\n\nfunction getMissingMediaNodeName(\n  item: ReturnType<typeof getMissingMediaItems>[number]\n): string | null {\n  return formatNodeTypeName(item.representative.nodeType)\n}\n\nfunction resolveMissingMediaDisplayMessage(): string {\n  return translateCatalogMessage(\n    'errorCatalog.missingErrors.missing_media.displayMessage',\n    'A required media input has no file selected.'\n  )\n}\n\nexport function resolveMissingMediaItemLabel(\n  source: MissingMediaItemLabelSource\n): { displayItemLabel: string } {\n  const nodeName = normalizeNodeName(\n    source.nodeDisplayName ||\n      formatNodeTypeName(source.nodeType ?? '') ||\n      undefined\n  )\n  const inputName =\n    source.widgetName?.trim() ||\n    translateCatalogMessage('errorCatalog.fallbacks.inputName', 'unknown input')\n\n  return {\n    displayItemLabel: translateCatalogMessage(\n      'errorCatalog.missingErrors.missing_media.itemLabel',\n      '{nodeName} - {inputName}',\n      { nodeName, inputName }\n    )\n  }\n}\n\nfunction resolveMissingMediaToastTitle(source: MissingMediaSource): string {\n  if (countMissingMediaReferences(source.groups) !== 1) {\n    return translateCatalogMessage(\n      'errorCatalog.missingErrors.missing_media.toastTitleMany',\n      'Missing media inputs'\n    )\n  }\n\n  return translateCatalogMessage(\n    'errorCatalog.missingErrors.missing_media.toastTitleOne',\n    'Media input missing'\n  )\n}\n\nfunction resolveMissingMediaToastMessage(source: MissingMediaSource): string {\n  const items = getMissingMediaItems(source)\n  const firstItem = items.at(0)\n  if (!firstItem || countMissingMediaReferences(source.groups) !== 1) {\n    return translateCatalogMessage(\n      'errorCatalog.missingErrors.missing_media.toastMessageMany',\n      'Please select the missing media inputs before running this workflow.'\n    )\n  }\n\n  const nodeName = getMissingMediaNodeName(firstItem)\n  const displayNodeName =\n    nodeName ??\n    translateCatalogMessage('errorCatalog.fallbacks.nodeName', 'This node')\n  return translateCatalogMessage(\n    'errorCatalog.missingErrors.missing_media.toastMessageWithNode',\n    '{nodeName} is missing a required media file.',\n    {\n      nodeName: displayNodeName\n    }\n  )\n}\n\nexport function resolveMissingErrorMessage(\n  source: MissingErrorMessageSource\n): ResolvedMissingErrorMessage {\n  switch (source.kind) {\n    case 'missing_node':\n      return {\n        catalogId: 'missing_node',\n        displayTitle: source.isCloud\n          ? st(\n              'rightSidePanel.missingNodePacks.unsupportedTitle',\n              'Unsupported Node Packs'\n            )\n          : st('rightSidePanel.missingNodePacks.title', 'Missing Node Packs'),\n        displayMessage: resolveMissingNodeDisplayMessage(source),\n        toastTitle: resolveMissingNodeToastTitle(source),\n        toastMessage: resolveMissingNodeToastMessage(source)\n      }\n    case 'swap_nodes':\n      return {\n        catalogId: 'swap_nodes',\n        displayTitle: st('nodeReplacement.swapNodesTitle', 'Swap Nodes'),\n        displayMessage: resolveSwapNodeDisplayMessage(),\n        toastTitle: resolveSwapNodeToastTitle(source),\n        toastMessage: resolveSwapNodeToastMessage(source)\n      }\n    case 'missing_model':\n      return {\n        catalogId: 'missing_model',\n        displayTitle: st(\n          'rightSidePanel.missingModels.missingModelsTitle',\n          'Missing Models'\n        ),\n        displayMessage: resolveMissingModelDisplayMessage(source),\n        toastTitle: resolveMissingModelToastTitle(source),\n        toastMessage: resolveMissingModelToastMessage(source)\n      }\n    case 'missing_media':\n      return {\n        catalogId: 'missing_media',\n        displayTitle: st(\n          'rightSidePanel.missingMedia.missingMediaTitle',\n          'Missing Inputs'\n        ),\n        displayMessage: resolveMissingMediaDisplayMessage(),\n        toastTitle: resolveMissingMediaToastTitle(source),\n        toastMessage: resolveMissingMediaToastMessage(source)\n      }\n  }\n}\n","import type {\n  ResolvedCatalogErrorMessage,\n  ResolvedErrorMessage,\n  RunErrorMessageSource\n} from './types'\n\nimport { resolveExecutionErrorMessage } from './executionErrorResolver'\nimport { resolvePromptErrorMessage } from './promptErrorResolver'\nimport { resolveNodeValidationErrorMessage } from './validationErrorResolver'\n\n// Public facade for error catalog resolution. Source-specific resolver modules\n// own the actual matching/copy rules so this file stays as the routing boundary.\nexport {\n  resolveMissingErrorMessage,\n  resolveMissingMediaItemLabel\n} from './missingErrorResolver'\n\nexport function resolveRunErrorMessage(\n  source: Extract<RunErrorMessageSource, { kind: 'node_validation' }>\n): ResolvedCatalogErrorMessage\nexport function resolveRunErrorMessage(\n  source: Extract<RunErrorMessageSource, { kind: 'execution' }>\n): ResolvedCatalogErrorMessage\nexport function resolveRunErrorMessage(\n  source: RunErrorMessageSource\n): ResolvedErrorMessage\nexport function resolveRunErrorMessage(\n  source: RunErrorMessageSource\n): ResolvedErrorMessage {\n  switch (source.kind) {\n    case 'node_validation':\n      return resolveNodeValidationErrorMessage(source.error, {\n        nodeDisplayName: source.nodeDisplayName\n      })\n    case 'prompt':\n      return resolvePromptErrorMessage(source.error, {\n        isCloud: source.isCloud\n      })\n    case 'execution':\n      return resolveExecutionErrorMessage(source.error, {\n        nodeDisplayName: source.nodeDisplayName\n      })\n  }\n}\n","import type { ISerialisedGraph } from '@/lib/litegraph/src/litegraph'\nimport type { SystemStats } from '@/platform/remote/comfyui/types'\nimport type { SerializedNodeId } from '@/types/nodeId'\n\nexport interface ErrorReportData {\n  exceptionType: string\n  exceptionMessage: string\n  systemStats: SystemStats\n  serverLogs: string\n  workflow: ISerialisedGraph\n\n  traceback?: string\n  nodeId?: SerializedNodeId\n  nodeType?: string\n}\n\n/**\n * Generate a report for an error.\n * @param error - The error to report.\n * @returns The report.\n */\nexport function generateErrorReport(error: ErrorReportData): string {\n  // The default JSON workflow has about 3000 characters.\n  const MAX_JSON_LENGTH = 20000\n  const workflowJSONString = JSON.stringify(error.workflow)\n  const workflowText =\n    workflowJSONString.length > MAX_JSON_LENGTH\n      ? 'Workflow too large. Please manually upload the workflow from local file system.'\n      : workflowJSONString\n  const systemStats = error.systemStats\n\n  return `\n# ComfyUI Error Report\n## Error Details\n- **Node ID:** ${error.nodeId || 'N/A'}\n- **Node Type:** ${error.nodeType || 'N/A'}\n- **Exception Type:** ${error.exceptionType || 'N/A'}\n- **Exception Message:** ${error.exceptionMessage || 'N/A'}\n## Stack Trace\n\\`\\`\\`\n${error.traceback || 'No stack trace available'}\n\\`\\`\\`\n## System Information\n- **ComfyUI Version:** ${systemStats.system.comfyui_version}\n- **Arguments:** ${systemStats.system.argv.join(' ')}\n- **OS:** ${systemStats.system.os}\n- **Python Version:** ${systemStats.system.python_version}\n- **Embedded Python:** ${systemStats.system.embedded_python}\n- **PyTorch Version:** ${systemStats.system.pytorch_version}\n## Devices\n${systemStats.devices\n  .map(\n    (device) => `\n- **Name:** ${device.name}\n  - **Type:** ${device.type}\n  - **VRAM Total:** ${device.vram_total}\n  - **VRAM Free:** ${device.vram_free}\n  - **Torch VRAM Total:** ${device.torch_vram_total}\n  - **Torch VRAM Free:** ${device.torch_vram_free}\n`\n  )\n  .join('\\n')}\n## Logs\n\\`\\`\\`\n${typeof error.serverLogs === 'string' ? error.serverLogs : JSON.stringify(error.serverLogs, null, 2)}\n\\`\\`\\`\n## Attached Workflow\nPlease make sure that workflow does not contain any sensitive information such as API keys or passwords.\n\\`\\`\\`\n${workflowText}\n\\`\\`\\`\n\n## Additional Context\n(Please add any additional context or steps to reproduce the error here)\n`\n}\n","<template>\n  <div\n    data-testid=\"error-dialog\"\n    class=\"comfy-error-report flex flex-col gap-4\"\n  >\n    <NoResultsPlaceholder\n      class=\"pb-0\"\n      icon=\"pi pi-exclamation-circle\"\n      :title=\"title\"\n      :message=\"message\"\n      text-class=\"break-words max-w-[60vw]\"\n    />\n    <template v-if=\"error.extensionFile\">\n      <span>{{ t('errorDialog.extensionFileHint') }}:</span>\n      <br />\n      <span class=\"font-bold\">{{ error.extensionFile }}</span>\n    </template>\n\n    <div class=\"flex justify-center gap-2\">\n      <Button\n        v-show=\"!reportOpen\"\n        data-testid=\"error-dialog-show-report\"\n        variant=\"textonly\"\n        @click=\"showReport\"\n      >\n        {{ $t('g.showReport') }}\n      </Button>\n      <Button\n        v-show=\"!reportOpen\"\n        data-testid=\"error-dialog-contact-support\"\n        variant=\"textonly\"\n        @click=\"showContactSupport\"\n      >\n        {{ $t('issueReport.helpFix') }}\n      </Button>\n    </div>\n    <template v-if=\"reportOpen\">\n      <hr class=\"border-t border-border-subtle\" />\n      <div class=\"h-[400px] w-full max-w-[80vw] overflow-auto\">\n        <pre class=\"wrap-break-word whitespace-pre-wrap\">{{\n          reportContent\n        }}</pre>\n      </div>\n      <hr class=\"border-t border-border-subtle\" />\n    </template>\n    <div class=\"flex justify-end gap-4\">\n      <FindIssueButton\n        :error-message=\"error.exceptionMessage\"\n        :repo-owner=\"repoOwner\"\n        :repo-name=\"repoName\"\n      />\n      <Button\n        v-if=\"reportOpen\"\n        data-testid=\"error-dialog-copy-report\"\n        @click=\"copyReportToClipboard\"\n      >\n        <i class=\"pi pi-copy\" />\n        {{ $t('g.copyToClipboard') }}\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { computed, onMounted, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport NoResultsPlaceholder from '@/components/common/NoResultsPlaceholder.vue'\nimport FindIssueButton from '@/components/dialog/content/error/FindIssueButton.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useCopyToClipboard } from '@/composables/useCopyToClipboard'\nimport { resolveRunErrorMessage } from '@/platform/errorCatalog/errorMessageResolver'\nimport type { RunErrorMessageSource } from '@/platform/errorCatalog/types'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { api } from '@/scripts/api'\nimport { useApp } from '@/scripts/appInstance'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useSystemStatsStore } from '@/stores/systemStatsStore'\nimport { generateErrorReport } from '@/utils/errorReportUtil'\nimport type { ErrorReportData } from '@/utils/errorReportUtil'\n\nconst { error, errorSources = [] } = defineProps<{\n  errorSources?: RunErrorMessageSource[]\n  error: Omit<ErrorReportData, 'workflow' | 'systemStats' | 'serverLogs'> & {\n    /**\n     * The type of error report to submit.\n     * @default 'unknownError'\n     */\n    reportType?: string\n    /**\n     * The file name of the extension that caused the error.\n     */\n    extensionFile?: string\n  }\n}>()\n\nconst repoOwner = 'comfyanonymous'\nconst repoName = 'ComfyUI'\nconst reportContent = ref('')\nconst reportOpen = ref(false)\n/**\n * Open the error report content and track telemetry.\n */\nconst showReport = () => {\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'error_dialog_show_report_clicked',\n    element_group: 'error_dialog'\n  })\n  reportOpen.value = true\n}\nconst toast = useToast()\nconst { t } = useI18n()\nconst systemStatsStore = useSystemStatsStore()\nconst telemetry = useTelemetry()\n\nconst resolvedErrors = computed(() =>\n  errorSources.map((source) => {\n    const resolved = resolveRunErrorMessage(source)\n    const rawMessage =\n      source.kind === 'execution'\n        ? source.error.exception_message\n        : resolved.displayMessage\n          ? source.error.details\n          : [source.error.message, source.error.details]\n              .filter(Boolean)\n              .join(': ')\n\n    return {\n      title: resolved.displayTitle,\n      message: [\n        source.kind === 'node_validation'\n          ? resolved.displayItemLabel\n          : undefined,\n        resolved.displayMessage,\n        resolved.displayDetails ?? rawMessage\n      ]\n        .filter(Boolean)\n        .join('\\n')\n    }\n  })\n)\nconst title = computed(\n  () =>\n    (errorSources[0]?.kind === 'execution' ? error.nodeType : undefined) ??\n    resolvedErrors.value[0]?.title ??\n    error.nodeType ??\n    error.exceptionType ??\n    t('errorDialog.defaultTitle')\n)\nconst message = computed(\n  () =>\n    resolvedErrors.value.map((resolved) => resolved.message).join('\\n\\n') ||\n    error.exceptionMessage\n)\n\n/**\n * Open contact support flow from error dialog and track telemetry.\n */\nconst showContactSupport = async () => {\n  telemetry?.trackHelpResourceClicked({\n    resource_type: 'help_feedback',\n    is_external: true,\n    source: 'error_dialog'\n  })\n  await useCommandStore().execute('Comfy.ContactSupport')\n}\n\nonMounted(async () => {\n  if (!systemStatsStore.systemStats) {\n    await systemStatsStore.refetchSystemStats()\n  }\n\n  try {\n    const logs = await api.getLogs()\n\n    reportContent.value = generateErrorReport({\n      systemStats: systemStatsStore.systemStats!,\n      serverLogs: logs,\n      workflow: useApp().rootGraph.serialize(),\n      exceptionType: error.exceptionType,\n      exceptionMessage: error.exceptionMessage,\n      traceback: error.traceback,\n      nodeId: error.nodeId,\n      nodeType: error.nodeType\n    })\n  } catch (error) {\n    console.error('Error fetching logs:', error)\n    toast.error(t('g.error'), {\n      description: t('toastMessages.failedToFetchLogs')\n    })\n  }\n})\n\nconst { copyToClipboard } = useCopyToClipboard()\nconst copyReportToClipboard = async () => {\n  await copyToClipboard(reportContent.value)\n}\n</script>\n","<template>\n  <div\n    data-testid=\"error-dialog\"\n    class=\"comfy-error-report flex flex-col gap-4\"\n  >\n    <NoResultsPlaceholder\n      class=\"pb-0\"\n      icon=\"pi pi-exclamation-circle\"\n      :title=\"title\"\n      :message=\"message\"\n      text-class=\"break-words max-w-[60vw]\"\n    />\n    <template v-if=\"error.extensionFile\">\n      <span>{{ t('errorDialog.extensionFileHint') }}:</span>\n      <br />\n      <span class=\"font-bold\">{{ error.extensionFile }}</span>\n    </template>\n\n    <div class=\"flex justify-center gap-2\">\n      <Button\n        v-show=\"!reportOpen\"\n        data-testid=\"error-dialog-show-report\"\n        variant=\"textonly\"\n        @click=\"showReport\"\n      >\n        {{ $t('g.showReport') }}\n      </Button>\n      <Button\n        v-show=\"!reportOpen\"\n        data-testid=\"error-dialog-contact-support\"\n        variant=\"textonly\"\n        @click=\"showContactSupport\"\n      >\n        {{ $t('issueReport.helpFix') }}\n      </Button>\n    </div>\n    <template v-if=\"reportOpen\">\n      <hr class=\"border-t border-border-subtle\" />\n      <div class=\"h-[400px] w-full max-w-[80vw] overflow-auto\">\n        <pre class=\"wrap-break-word whitespace-pre-wrap\">{{\n          reportContent\n        }}</pre>\n      </div>\n      <hr class=\"border-t border-border-subtle\" />\n    </template>\n    <div class=\"flex justify-end gap-4\">\n      <FindIssueButton\n        :error-message=\"error.exceptionMessage\"\n        :repo-owner=\"repoOwner\"\n        :repo-name=\"repoName\"\n      />\n      <Button\n        v-if=\"reportOpen\"\n        data-testid=\"error-dialog-copy-report\"\n        @click=\"copyReportToClipboard\"\n      >\n        <i class=\"pi pi-copy\" />\n        {{ $t('g.copyToClipboard') }}\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { computed, onMounted, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport NoResultsPlaceholder from '@/components/common/NoResultsPlaceholder.vue'\nimport FindIssueButton from '@/components/dialog/content/error/FindIssueButton.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useCopyToClipboard } from '@/composables/useCopyToClipboard'\nimport { resolveRunErrorMessage } from '@/platform/errorCatalog/errorMessageResolver'\nimport type { RunErrorMessageSource } from '@/platform/errorCatalog/types'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { api } from '@/scripts/api'\nimport { useApp } from '@/scripts/appInstance'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useSystemStatsStore } from '@/stores/systemStatsStore'\nimport { generateErrorReport } from '@/utils/errorReportUtil'\nimport type { ErrorReportData } from '@/utils/errorReportUtil'\n\nconst { error, errorSources = [] } = defineProps<{\n  errorSources?: RunErrorMessageSource[]\n  error: Omit<ErrorReportData, 'workflow' | 'systemStats' | 'serverLogs'> & {\n    /**\n     * The type of error report to submit.\n     * @default 'unknownError'\n     */\n    reportType?: string\n    /**\n     * The file name of the extension that caused the error.\n     */\n    extensionFile?: string\n  }\n}>()\n\nconst repoOwner = 'comfyanonymous'\nconst repoName = 'ComfyUI'\nconst reportContent = ref('')\nconst reportOpen = ref(false)\n/**\n * Open the error report content and track telemetry.\n */\nconst showReport = () => {\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'error_dialog_show_report_clicked',\n    element_group: 'error_dialog'\n  })\n  reportOpen.value = true\n}\nconst toast = useToast()\nconst { t } = useI18n()\nconst systemStatsStore = useSystemStatsStore()\nconst telemetry = useTelemetry()\n\nconst resolvedErrors = computed(() =>\n  errorSources.map((source) => {\n    const resolved = resolveRunErrorMessage(source)\n    const rawMessage =\n      source.kind === 'execution'\n        ? source.error.exception_message\n        : resolved.displayMessage\n          ? source.error.details\n          : [source.error.message, source.error.details]\n              .filter(Boolean)\n              .join(': ')\n\n    return {\n      title: resolved.displayTitle,\n      message: [\n        source.kind === 'node_validation'\n          ? resolved.displayItemLabel\n          : undefined,\n        resolved.displayMessage,\n        resolved.displayDetails ?? rawMessage\n      ]\n        .filter(Boolean)\n        .join('\\n')\n    }\n  })\n)\nconst title = computed(\n  () =>\n    (errorSources[0]?.kind === 'execution' ? error.nodeType : undefined) ??\n    resolvedErrors.value[0]?.title ??\n    error.nodeType ??\n    error.exceptionType ??\n    t('errorDialog.defaultTitle')\n)\nconst message = computed(\n  () =>\n    resolvedErrors.value.map((resolved) => resolved.message).join('\\n\\n') ||\n    error.exceptionMessage\n)\n\n/**\n * Open contact support flow from error dialog and track telemetry.\n */\nconst showContactSupport = async () => {\n  telemetry?.trackHelpResourceClicked({\n    resource_type: 'help_feedback',\n    is_external: true,\n    source: 'error_dialog'\n  })\n  await useCommandStore().execute('Comfy.ContactSupport')\n}\n\nonMounted(async () => {\n  if (!systemStatsStore.systemStats) {\n    await systemStatsStore.refetchSystemStats()\n  }\n\n  try {\n    const logs = await api.getLogs()\n\n    reportContent.value = generateErrorReport({\n      systemStats: systemStatsStore.systemStats!,\n      serverLogs: logs,\n      workflow: useApp().rootGraph.serialize(),\n      exceptionType: error.exceptionType,\n      exceptionMessage: error.exceptionMessage,\n      traceback: error.traceback,\n      nodeId: error.nodeId,\n      nodeType: error.nodeType\n    })\n  } catch (error) {\n    console.error('Error fetching logs:', error)\n    toast.error(t('g.error'), {\n      description: t('toastMessages.failedToFetchLogs')\n    })\n  }\n})\n\nconst { copyToClipboard } = useCopyToClipboard()\nconst copyReportToClipboard = async () => {\n  await copyToClipboard(reportContent.value)\n}\n</script>\n","<template>\n  <div class=\"prompt-dialog-content flex flex-col gap-2 pt-8\">\n    <label class=\"flex flex-col gap-1 text-sm text-muted-foreground\">\n      {{ message }}\n      <Input\n        ref=\"inputRef\"\n        v-model=\"inputValue\"\n        type=\"text\"\n        :placeholder\n        autofocus\n        @keyup.enter=\"handleConfirm\"\n        @focus=\"inputRef?.selectAll()\"\n      />\n    </label>\n    <Button @click=\"handleConfirm\">\n      {{ $t('g.confirm') }}\n    </Button>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Input from '@/components/ui/input/Input.vue'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nconst { message, defaultValue, onConfirm, placeholder } = defineProps<{\n  message: string\n  defaultValue: string\n  onConfirm: (value: string) => void\n  placeholder?: string\n}>()\n\ncon